mapper.select:
SELECT g.id, g.name, g.storage, g.goodsType, g.count, g.min_count AS minCount, g.barcode, g.specs, g.unit, g.retail_price AS retailPrice, g.purchase_price AS purchasePrice, g.supplier_id AS supplierId, s.name AS supplierName, gt.name AS categoryName, st.name AS warehouseName, g.remark FROM goods g LEFT JOIN supplier s ON g.supplier_id = s.id LEFT JOIN goodstype gt ON g.goodsType = gt.id LEFT JOIN storage st ON g.storage = st.id
AND g.name LIKE CONCAT('%', #{name}, '%')
AND g.goodsType = #{goodsType}
AND g.storage = #{storage}
AND g.count <= g.min_count
ORDER BY g.id DESC
